const originalText=new Map();
document.querySelectorAll("[data-i18n]").forEach(el=>originalText.set(el.dataset.i18n,el.innerHTML));
let language="vi",activeGallery="kdtc",currentLightboxItems=[],currentLightboxIndex=0;
const header=document.querySelector(".site-header"),menuButton=document.querySelector(".menu-toggle"),nav=document.querySelector(".main-nav"),langButtons=document.querySelectorAll(".lang-toggle [data-lang]"),evidenceGrid=document.querySelector("#evidence-grid"),lightbox=document.querySelector("#lightbox"),lightboxImage=lightbox.querySelector("img"),lightboxCaption=lightbox.querySelector("figcaption");
