menuButton.addEventListener("click",()=>{const open=nav.classList.toggle("open");menuButton.setAttribute("aria-expanded",String(open));});
nav.querySelectorAll("a").forEach(link=>link.addEventListener("click",()=>{nav.classList.remove("open");menuButton.setAttribute("aria-expanded","false");}));
function setLanguage(next){language=next;document.documentElement.lang=language==="zh"?"zh-CN":language;document.querySelectorAll("[data-i18n]").forEach(el=>{const key=el.dataset.i18n;el.innerHTML=language==="vi"?originalText.get(key):translations[language]?.[key]??originalText.get(key);});langButtons.forEach(button=>button.classList.toggle("active",button.dataset.lang===language));renderGallery(activeGallery);}
langButtons.forEach(button=>button.addEventListener("click",()=>setLanguage(button.dataset.lang)));
function localizedCaption(key){return captions[language]?.[key]||key;}
function renderGallery(group){activeGallery=group;const items=galleryData[group];evidenceGrid.innerHTML=items.map(([src,key],index)=>`<button class="evidence-item" data-evidence-index="${index}" aria-label="${localizedCaption(key)}"><span class="thumb"><img src="${src}" alt="${localizedCaption(key)}" loading="lazy"></span><span><b>${localizedCaption(key)}</b><small>${String(index+1).padStart(2,"0")} / ${String(items.length).padStart(2,"0")}</small></span></button>`).join("");document.querySelectorAll(".evidence-tabs button").forEach(button=>button.classList.toggle("active",button.dataset.gallery===group));evidenceGrid.querySelectorAll(".evidence-item").forEach(button=>button.addEventListener("click",()=>{currentLightboxItems=items.map(([src,key])=>({src,caption:localizedCaption(key)}));openLightbox(Number(button.dataset.evidenceIndex));}));}
function showLightboxItem(){const item=currentLightboxItems[currentLightboxIndex];lightboxImage.src=item.src;lightboxImage.alt=item.caption;lightboxCaption.textContent=`${item.caption} — ${currentLightboxIndex+1}/${currentLightboxItems.length}`;const multiple=currentLightboxItems.length>1;lightbox.querySelector(".lightbox-prev").hidden=!multiple;lightbox.querySelector(".lightbox-next").hidden=!multiple;}
function openLightbox(index=0){currentLightboxIndex=index;showLightboxItem();lightbox.showModal();}
function moveLightbox(direction){currentLightboxIndex=(currentLightboxIndex+direction+currentLightboxItems.length)%currentLightboxItems.length;showLightboxItem();}
document.querySelectorAll(".evidence-tabs button").forEach(button=>button.addEventListener("click",()=>renderGallery(button.dataset.gallery)));
document.querySelectorAll("[data-lightbox-src]").forEach(el=>el.addEventListener("click",event=>{event.preventDefault();currentLightboxItems=[{src:el.dataset.lightboxSrc,caption:el.dataset.lightboxCaption||""}];openLightbox();}));
lightbox.querySelector(".lightbox-close").addEventListener("click",()=>lightbox.close());lightbox.querySelector(".lightbox-prev").addEventListener("click",()=>moveLightbox(-1));lightbox.querySelector(".lightbox-next").addEventListener("click",()=>moveLightbox(1));lightbox.addEventListener("click",event=>{if(event.target===lightbox)lightbox.close();});document.addEventListener("keydown",event=>{if(!lightbox.open)return;if(event.key==="ArrowLeft")moveLightbox(-1);if(event.key==="ArrowRight")moveLightbox(1);});
const revealObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add("visible");revealObserver.unobserve(entry.target);}}),{threshold:.12});document.querySelectorAll(".reveal").forEach(el=>revealObserver.observe(el));
const counterObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(!entry.isIntersecting)return;const el=entry.target,target=Number(el.dataset.count),decimals=Number(el.dataset.decimals||0),duration=1300,start=performance.now();const tick=now=>{const progress=Math.min((now-start)/duration,1),eased=1-Math.pow(1-progress,3);el.textContent=(target*eased).toFixed(decimals);if(progress<1)requestAnimationFrame(tick);};requestAnimationFrame(tick);counterObserver.unobserve(el);}),{threshold:.5});document.querySelectorAll("[data-count]").forEach(el=>counterObserver.observe(el));
renderGallery(activeGallery);
